import { useState } from 'react';
import { BoardCodeForm } from './BoardCodeForm.tsx';
import { ReproductionControl } from './control-labels.ts';
import type { GameState } from '../game.ts';
import './control.css';
import './reproduction.css';

const SNAPSHOT_MAX_CHARACTERS = 65_536;

interface ReproductionProps {
  game: GameState;
  generation: number;
  exportSnapshot(): string;
  loadBoard(code: string): boolean;
  loadSnapshot(text: string): boolean;
  notice: string;
  paused: boolean;
  resume(): void;
}

export function Reproduction({
  game,
  generation,
  exportSnapshot,
  loadBoard,
  loadSnapshot,
  notice,
  paused,
  resume,
}: ReproductionProps) {
  const [snapshot, setSnapshot] = useState('');
  return (
    <>
      <details className="reproduction">
        <summary>{ReproductionControl.summary}</summary>
        <div className="reproduction-body">
          <BoardCodeForm code={game.boardCode} generation={generation} loadBoard={loadBoard} />
          <label htmlFor="snapshot-json">{ReproductionControl.snapshot}</label>
          <textarea
            id="snapshot-json"
            className="control"
            rows={5}
            value={snapshot}
            maxLength={SNAPSHOT_MAX_CHARACTERS}
            spellCheck={false}
            onChange={(event) => setSnapshot(event.currentTarget.value)}
          />
          <div className="control-row">
            <button type="button" className="control" onClick={() => setSnapshot(exportSnapshot())}>
              {ReproductionControl.exportSnapshot}
            </button>
            <button
              type="button"
              className="control"
              aria-describedby="load-notice"
              onClick={() => loadSnapshot(snapshot)}
            >
              {ReproductionControl.loadSnapshot}
            </button>
          </div>
        </div>
      </details>
      <div className="load-status">
        <p id="load-notice" className="load-notice">
          {notice}
        </p>
        {paused && (
          <button type="button" className="control" onClick={resume}>
            {ReproductionControl.resume}
          </button>
        )}
      </div>
    </>
  );
}

import { generateBoard } from './deck.ts';
import { SelectionKind } from './selection.ts';
import type { Board } from './deck.ts';
import type { Selection } from './selection.ts';

export const ELAPSED_MAX_MS = 359_999_999;
export const MISMATCH_MS = 800;
export const MOVES_MAX = 999_999;

export interface GameState extends Board {
  readonly matched: readonly number[];
  readonly selection: Selection;
  readonly moves: number;
  readonly elapsedMs: number;
  readonly started: boolean;
}

export function createGame(boardCode: string): GameState {
  return {
    ...generateBoard(boardCode),
    matched: [],
    selection: { kind: SelectionKind.closed },
    moves: 0,
    elapsedMs: 0,
    started: false,
  };
}

export function isWon(state: GameState): boolean {
  return state.matched.length === state.deck.length;
}

// The board reads one set per game state instead of searching the matched list for every card.
export function faceUpCards(state: Pick<GameState, 'matched' | 'selection'>): ReadonlySet<number> {
  const cards = new Set(state.matched);
  const selection = state.selection;
  if (selection.kind === SelectionKind.one) cards.add(selection.index);
  if (selection.kind === SelectionKind.mismatch) {
    cards.add(selection.first);
    cards.add(selection.second);
  }
  return cards;
}

export function activateCard(state: GameState, index: number): GameState {
  if (!Number.isInteger(index) || index < 0 || index >= state.deck.length) return state;
  if (state.matched.includes(index)) return state;
  switch (state.selection.kind) {
    case SelectionKind.closed:
      return { ...state, started: true, selection: { kind: SelectionKind.one, index } };
    case SelectionKind.one: {
      const first = state.selection.index;
      if (first === index) return state;
      const moves = Math.min(MOVES_MAX, state.moves + 1);
      if (state.deck[first] === state.deck[index]) {
        return {
          ...state,
          moves,
          matched: [...state.matched, first, index],
          selection: { kind: SelectionKind.closed },
        };
      }
      return {
        ...state,
        moves,
        selection: { kind: SelectionKind.mismatch, first, second: index, remainingMs: MISMATCH_MS },
      };
    }
    case SelectionKind.mismatch:
      return state;
    default:
      return unreachable(state.selection);
  }
}

export function advanceGame(state: GameState, milliseconds: number): GameState {
  if (!Number.isFinite(milliseconds) || milliseconds <= 0) return state;
  if (!state.started || isWon(state)) return state;
  const elapsedMs = Math.min(ELAPSED_MAX_MS, state.elapsedMs + milliseconds);
  if (state.selection.kind !== SelectionKind.mismatch) return { ...state, elapsedMs };
  const remainingMs = state.selection.remainingMs - milliseconds;
  const selection =
    remainingMs > 0 ? { ...state.selection, remainingMs } : { kind: SelectionKind.closed };
  return { ...state, elapsedMs, selection };
}

function unreachable(value: never): never {
  throw new Error(`Unknown selection: ${String(value)}`);
}

import assert from 'node:assert/strict';
import { test } from 'vitest';
import { activateCard, advanceGame, createGame, MISMATCH_MS, MOVES_MAX } from './game.ts';
import {
  decodeSnapshot,
  encodeSnapshot,
  SNAPSHOT_KEYS,
  SNAPSHOT_MAX_BYTES,
  SNAPSHOT_VERSION,
} from './snapshot.ts';
import { SelectionKind } from './selection.ts';
import { EXAMPLE_CODE, EXAMPLE_PAIRS, SPEC_VECTOR } from './game.fixture.ts';

function snapshot(overrides: Record<string, unknown> = {}): string {
  return JSON.stringify({
    version: SNAPSHOT_VERSION,
    boardCode: EXAMPLE_CODE,
    matched: [],
    selection: { kind: SelectionKind.closed },
    moves: 0,
    elapsedMs: 0,
    started: false,
    ...overrides,
  });
}

test('snapshot round trips preserve pending time and serialize only the declared fields', () => {
  const state = advanceGame(activateCard(activateCard(createGame(EXAMPLE_CODE), 0), 1), 175);
  assert.deepEqual(decodeSnapshot(encodeSnapshot(state)), state);
  assert.deepEqual(state.selection, {
    kind: SelectionKind.mismatch,
    first: 0,
    second: 1,
    remainingMs: MISMATCH_MS - 175,
  });
  assert.equal(SNAPSHOT_VERSION, SPEC_VECTOR.snapshotVersion);
  assert.equal(SNAPSHOT_MAX_BYTES, SPEC_VECTOR.snapshotBytes);
  const exported: unknown = JSON.parse(encodeSnapshot(state));
  assert.ok(exported && typeof exported === 'object');
  assert.deepEqual(Object.keys(exported).sort(), [...SNAPSHOT_KEYS].sort());
});

test('snapshots accept whole pairs and completed states without changing the source order', () => {
  const state = activateCard(activateCard(createGame(EXAMPLE_CODE), 6), 2);
  assert.deepEqual(decodeSnapshot(encodeSnapshot(state))?.matched, [2, 6]);
  assert.deepEqual(state.matched, [6, 2]);
  assert.equal(
    decodeSnapshot(
      snapshot({ matched: EXAMPLE_PAIRS.flat(), moves: EXAMPLE_PAIRS.length, started: true }),
    )?.matched.length,
    16,
  );
  assert.ok(decodeSnapshot(snapshot({ moves: 17, started: true })));
});

const INVALID_SNAPSHOTS: readonly Record<string, unknown>[] = [
  { extra: true },
  { version: 2 },
  { boardCode: 'np1-4-0' },
  { elapsedMs: -1 },
  { elapsedMs: 0.5 },
  { moves: Number.MAX_SAFE_INTEGER + 1 },
  { moves: -1 },
  { started: 'true' },
  { matched: [0] },
  { matched: [0, 1] },
  { matched: [2, 6, 2, 6] },
  { matched: [2, 16] },
  { matched: [2, 6], started: true, moves: 0 },
  { selection: { kind: SelectionKind.one, index: 16 }, started: true },
  { selection: { kind: SelectionKind.one, index: 2, extra: true }, started: true },
  { selection: { kind: SelectionKind.one, index: 2 }, started: false },
  { started: true },
  { moves: 1 },
  { elapsedMs: 1 },
  { selection: { kind: 'unknown' } },
  {
    selection: { kind: SelectionKind.mismatch, first: 2, second: 6, remainingMs: 1 },
    started: true,
    moves: 1,
  },
  {
    selection: { kind: SelectionKind.mismatch, first: 0, second: 0, remainingMs: 1 },
    started: true,
    moves: 1,
  },
  {
    selection: { kind: SelectionKind.mismatch, first: 0, second: 1, remainingMs: 0 },
    started: true,
    moves: 1,
  },
  {
    selection: { kind: SelectionKind.mismatch, first: 0, second: 1, remainingMs: MISMATCH_MS + 1 },
    started: true,
    moves: 1,
  },
  { matched: [2, 6], selection: { kind: SelectionKind.one, index: 2 }, started: true, moves: 1 },
  { moves: MOVES_MAX + 1, started: true },
];
for (const [index, overrides] of INVALID_SNAPSHOTS.entries()) {
  test(`snapshot validation rejects inconsistent state ${index + 1}`, () => {
    assert.equal(
      decodeSnapshot(snapshot(overrides)),
      null,
      `snapshot rejects isolated field case ${index + 1}`,
    );
  });
}

// Started play with one revealed card is valid at zero moves, so each variant breaks one rule.
const ONE_REVEALED = { started: true, selection: { kind: SelectionKind.one, index: 0 } };
const PENDING = {
  started: true,
  moves: 1,
  selection: { kind: SelectionKind.mismatch, first: 0, second: 1, remainingMs: MISMATCH_MS },
};

test('started progress rejects a nonboolean flag and negative or fractional counters', () => {
  assert.ok(decodeSnapshot(snapshot(ONE_REVEALED)), 'valid started baseline');
  const nonboolean = snapshot({ ...ONE_REVEALED, started: 'true' });
  assert.equal(decodeSnapshot(nonboolean), null, 'nonboolean started');
  for (const field of ['moves', 'elapsedMs'])
    for (const value of [-1, 0.5])
      assert.equal(
        decodeSnapshot(snapshot({ ...ONE_REVEALED, [field]: value })),
        null,
        `${field} must be a nonnegative integer`,
      );
});

test('progress needs one move per matched pair and one for a pending mismatch', () => {
  assert.ok(decodeSnapshot(snapshot(PENDING)), 'valid mismatch baseline');
  const unpaid = snapshot({ ...PENDING, moves: 0 });
  assert.equal(decodeSnapshot(unpaid), null, 'pending mismatch needs one move');
  const twoPairs = {
    ...ONE_REVEALED,
    matched: [2, 6, 0, 11],
    moves: 2,
    selection: { kind: SelectionKind.one, index: 3 },
  };
  assert.ok(decodeSnapshot(snapshot(twoPairs)), 'valid two-pair baseline');
  const short = snapshot({ ...twoPairs, moves: 1 });
  assert.equal(decodeSnapshot(short), null, 'matched pairs need two moves');
});

// Quarter milliseconds are exact in binary.
const BEFORE_MISMATCH_MS = 11;
const INTO_MISMATCH_MS = 0.75;
const NEAR_CLOSE_MS = MISMATCH_MS - 0.25;

test('export writes whole milliseconds and keeps a pending mismatch at 1ms or more', () => {
  const first = activateCard(createGame(EXAMPLE_CODE), 0);
  const mismatch = activateCard(advanceGame(first, BEFORE_MISMATCH_MS), 1);
  for (const milliseconds of [INTO_MISMATCH_MS, NEAR_CLOSE_MS]) {
    const state = advanceGame(mismatch, milliseconds);
    // Import accepts only whole elapsed time and a pending mismatch from 1ms through 800ms.
    const exported = decodeSnapshot(encodeSnapshot(state));
    assert.ok(exported, 'C08 export has whole milliseconds and pending time of at least 1ms');
    assert.ok(Math.abs(exported.elapsedMs - state.elapsedMs) < 1, 'C08 elapsed time is within 1ms');
    assert.ok(
      exported.selection.kind === SelectionKind.mismatch &&
        state.selection.kind === SelectionKind.mismatch &&
        Math.abs(exported.selection.remainingMs - state.selection.remainingMs) < 1,
      'C08 pending time is within 1ms',
    );
  }
  assert.equal(advanceGame(mismatch, NEAR_CLOSE_MS).selection.kind, SelectionKind.mismatch);
  assert.equal(advanceGame(mismatch, MISMATCH_MS).selection.kind, SelectionKind.closed);
});

test('snapshot parsing enforces malformed, missing and exact byte limits', () => {
  for (const text of ['null', '[]', '{}', '{']) assert.equal(decodeSnapshot(text), null);
  const text = snapshot();
  const padded = text + ' '.repeat(SNAPSHOT_MAX_BYTES - Buffer.byteLength(text));
  assert.ok(decodeSnapshot(padded));
  assert.equal(decodeSnapshot(padded + ' '), null);
});

import assert from 'node:assert/strict';
import { test } from 'vitest';
import {
  hasExactKeys,
  isJsonObject,
  isNonnegativeSafeInteger,
  isWithinBytes,
  parseJson,
} from './saved-format.ts';

test('JSON limits count UTF-8 bytes before parsing', () => {
  const text = JSON.stringify('\u00e9');
  const bytes = Buffer.byteLength(text, 'utf8');
  assert.equal(isWithinBytes(text, bytes), true);
  assert.equal(isWithinBytes(text, bytes - 1), false);
  assert.equal(parseJson(text), '\u00e9');
  assert.equal(parseJson('{'), undefined);
});

test('unknown input needs an object, exact own keys and nonnegative safe integers', () => {
  for (const value of [null, [], 'value', 1]) assert.equal(isJsonObject(value), false);
  assert.equal(isJsonObject({}), true);
  assert.equal(hasExactKeys({ a: 1 }, ['a']), true);
  assert.equal(hasExactKeys({ a: 1, b: 2 }, ['a']), false);
  assert.equal(hasExactKeys({}, ['a']), false);
  for (const value of [-1, 0.5, NaN, Infinity, Number.MAX_SAFE_INTEGER + 1, '1']) {
    assert.equal(isNonnegativeSafeInteger(value), false);
  }
  assert.equal(isNonnegativeSafeInteger(0), true);
  assert.equal(isNonnegativeSafeInteger(Number.MAX_SAFE_INTEGER), true);
});

