import { useRef, useState } from 'react';
import { createGame } from '../game.ts';
import { parseBoardCode, isValidSize } from '../deck.ts';
import { decodeSnapshot, encodeSnapshot } from '../snapshot.ts';
import { freshBoardCode } from './fresh-board.ts';
import { activateSession, initialSession, nameGame, replaceGame, SessionNotice } from './session.ts';
import { readPreferences } from './storage.ts';
import { browserStore, useSavedPreferences } from './use-saved-preferences.ts';
import { useSessionClock } from './use-session-clock.ts';
import type { Session } from './session.ts';

export function useGame() {
  const [store] = useState(browserStore);
  const [session, setSession] = useState(() => {
    const preferences = readPreferences(store);
    return initialSession(freshBoardCode(preferences.size), preferences);
  });
  const current = useRef(session);

  function commit(next: Session): void {
    if (next === current.current) return;
    current.current = next;
    setSession(next);
  }

  const clock = useSessionClock(session, current, commit);
  useSavedPreferences(store, session.preferences);

  function newGame(size = current.current.game.size): void {
    if (!isValidSize(size)) return;
    const next = createGame(freshBoardCode(size, current.current.game.seed));
    clock.reset();
    commit(replaceGame(current.current, next, false));
  }

  function restart(): void {
    clock.reset();
    commit(replaceGame(current.current, createGame(current.current.game.boardCode), false));
  }

  function notice(feedback: string): void {
    commit({
      ...current.current,
      feedback,
      loadNotice: feedback,
      announcement: current.current.announcement + 1,
    });
  }

  function loadBoard(code: string): boolean {
    code = code.trim();
    if (!parseBoardCode(code)) {
      notice(SessionNotice.invalidBoard);
      return false;
    }
    clock.reset();
    commit(replaceGame(current.current, createGame(code), false));
    return true;
  }

  function loadSnapshot(text: string): boolean {
    const game = decodeSnapshot(text);
    if (!game) {
      notice(SessionNotice.invalidSnapshot);
      return false;
    }
    clock.reset();
    commit(replaceGame(current.current, game, true));
    return true;
  }

  function exportSnapshot(): string {
    // Rendered state can trail the active clock by a tick.
    clock.synchronize();
    return encodeSnapshot(current.current.game);
  }

  function activate(index: number): void {
    clock.synchronize();
    commit(activateSession(current.current, index));
  }

  function resume(): void {
    clock.reset();
    commit({
      ...current.current,
      paused: false,
      feedback: '',
      loadNotice: '',
    });
  }

  function setName(name: string): void {
    commit(nameGame(current.current, name));
  }

  return {
    session,
    newGame,
    restart,
    loadBoard,
    loadSnapshot,
    exportSnapshot,
    activate,
    resume,
    setName,
  };
}

import assert from 'node:assert/strict';
import { test } from 'vitest';
import { activateCard, createGame } from './game.ts';
import { isJsonObject } from './saved-format.ts';
import {
  decodeSnapshot,
  encodeSnapshot,
  isValidDealName,
  NAMED_SNAPSHOT_VERSION,
  SNAPSHOT_VERSION,
} from './snapshot.ts';
import { SelectionKind } from './selection.ts';
import { EXAMPLE_CODE } from './game.fixture.ts';

test('unnamed progress keeps version one and named progress round trips in version two', () => {
  const unnamed = encodeSnapshot(createGame(EXAMPLE_CODE));
  const unnamedSaved: unknown = JSON.parse(unnamed);
  assert.ok(isJsonObject(unnamedSaved));
  assert.equal(unnamedSaved.version, SNAPSHOT_VERSION);

  const game = { ...activateCard(createGame(EXAMPLE_CODE), 0), name: '  Café 🙂  ' };
  const encoded = encodeSnapshot(game);
  const saved: unknown = JSON.parse(encoded);
  assert.ok(isJsonObject(saved));
  assert.equal(saved.version, NAMED_SNAPSHOT_VERSION);
  assert.equal(saved.name, game.name);
  assert.deepEqual(decodeSnapshot(encoded), game);
});

test('pasted snapshots accept exact fields in arbitrary property order', () => {
  const unnamed = JSON.stringify({
    started: false,
    selection: { kind: SelectionKind.closed },
    elapsedMs: 0,
    moves: 0,
    matched: [],
    boardCode: EXAMPLE_CODE,
    version: SNAPSHOT_VERSION,
  });
  assert.ok(decodeSnapshot(unnamed));

  const named = JSON.stringify({
    started: true,
    selection: { kind: SelectionKind.one, index: 0 },
    elapsedMs: 0,
    moves: 0,
    matched: [],
    boardCode: EXAMPLE_CODE,
    name: 'Café',
    version: NAMED_SNAPSHOT_VERSION,
  });
  assert.equal(decodeSnapshot(named)?.name, 'Café');
});

test('version two requires a valid name and version one rejects extra name fields', () => {
  const base = {
    boardCode: EXAMPLE_CODE,
    matched: [],
    selection: { kind: SelectionKind.closed },
    moves: 0,
    elapsedMs: 0,
    started: false,
  };
  for (const name of ['', 'x'.repeat(41), 'line\nbreak', 'line\rbreak']) {
    assert.equal(decodeSnapshot(JSON.stringify({ ...base, version: 2, name })), null);
  }
  assert.equal(decodeSnapshot(JSON.stringify({ ...base, version: 1, name: 'extra' })), null);
  assert.equal(isValidDealName('😀'.repeat(20)), true);
  assert.equal(isValidDealName('😀'.repeat(21)), false);
});

